/* =====================================================================
   Banco de preguntas · Física 3 · S13 · Autoinducción e inductancia
   Plantillas parametrizadas, todas propias (source: 'propia'). Unidades SI,
   μ₀ = 4π × 10⁻⁷ T·m/A. La inductancia mutua es solo un detalle de la lección:
   no tiene preguntas. concept: true = conceptual. Cada numérica trae
   oracle(v, LM): la respuesta recalculada con LabMath.inductor
   (lo comprueba scripts/labs-math/inductance-solenoid.js).
   ===================================================================== */
(function () {
  var K = window.CBBankKit('f3', '13');
  var MU0 = 4 * Math.PI * 1e-7, TAU = 2 * Math.PI;
  var SCI = ' Responde con notación científica.';
  function fx(v, d) { return Number(v.toFixed(d == null ? 2 : d)).toString(); }
  var IN = function (LM) { return LM.inductor; };
  function area(r) { return Math.PI * Math.pow(r / 100, 2); }
  function Lsol(N, r, l, Km) { return (Km || 1) * MU0 * N * N * area(r) / (l / 100); }

  function distinct(q) {
    return function (v) {
      if (q.baseWhere && !q.baseWhere(v)) return false;
      var vals = [q.answer(v)].concat(Object.keys(q.mistakes).map(function (k) { return q.mistakes[k](v); }));
      for (var i = 0; i < vals.length; i++) {
        if (!isFinite(vals[i])) return false;
        for (var j = i + 1; j < vals.length; j++) {
          var big = Math.max(Math.abs(vals[i]), Math.abs(vals[j])), small = Math.min(Math.abs(vals[i]), Math.abs(vals[j]));
          if (Math.abs(vals[i] - vals[j]) <= Math.max(0.03 * big, small >= 0.09 ? 0.025 : 0)) return false;
        }
      }
      return true;
    };
  }
  function N(id, sub, d, vars, prompt, answer, why, o, oracle) {
    o = o || {};
    var q = K.N(id, sub, d, vars, prompt, answer, why, o);
    if (o.mistakes) { q.baseWhere = o.where; q.where = distinct(q); }
    q.oracle = oracle;
    return q;
  }
  var C = K.C;

  var Q = [
    /* ======================= Autoinducción ======================= */
    C('au-def', 'autoinduccion', 1, '¿Qué es la autoinducción?', 'La fem que se induce en un circuito cuando cambia su propia corriente',
      [['La corriente que circula sin fuente', 'Es una fem que aparece cuando la corriente cambia.'], ['La fem que induce un imán externo', 'Esa es inducción por una fuente externa; la autoinducción viene de la propia corriente.'], ['La resistencia de una bobina', 'La resistencia no es inducción.']],
      'El flujo propio cambia con la corriente.'),
    C('au-constante', 'autoinduccion', 1, 'Por una bobina ideal circula una corriente directa constante. La fem autoinducida es…', 'cero',
      [['máxima', 'Sin cambio de corriente no hay fem.'], ['igual a $LI$', '$LI$ es el enlace de flujo, no la fem.'], ['negativa', 'Es cero.']],
      '$dI/dt = 0$.'),
    C('au-opone', 'autoinduccion', 1, 'La fem autoinducida en una bobina se opone a…', 'el cambio de la corriente',
      [['la corriente, aunque sea constante', 'Con corriente constante no hay fem.'], ['el voltaje de la fuente siempre', 'Si la corriente baja, empuja a favor.'], ['el campo magnético de la Tierra', 'No tiene que ver con la Tierra.']],
      'Ley de Lenz aplicada a la propia bobina.'),
    C('au-chispa', 'autoinduccion', 2, '¿Por qué salta una chispa al desconectar de golpe un aparato con motor?', 'Porque la corriente cae muy rápido y la fem autoinducida es muy grande',
      [['Porque el motor se queda con carga eléctrica', 'No es carga acumulada; es la fem $L\\,dI/dt$.'], ['Porque el enchufe se calienta', 'El calor no hace saltar chispas así.'], ['Porque la corriente aumenta al desconectar', 'Disminuye, pero muy rápido.']],
      '$|\\varepsilon| = L\\,|dI/dt|$ con $dI/dt$ enorme.'),
    C('au-cierra', 'autoinduccion', 2, 'Al cerrar el interruptor de un circuito con una bobina, la corriente…', 'sube poco a poco, porque la fem autoinducida se opone al aumento',
      [['salta a su valor final al instante', 'La bobina frena el aumento.'], ['se queda en cero', 'Sí sube, pero gradualmente.'], ['sube y luego baja a cero', 'Sube hasta su valor final y ahí se queda.']],
      'La “inercia” de la bobina.'),
    C('au-ayuda', 'autoinduccion', 2, 'Si la corriente de una bobina está disminuyendo, la fem autoinducida…', 'empuja a favor de la corriente, para sostenerla',
      [['empuja en contra de la corriente', 'En contra sería si la corriente aumentara.'], ['es cero', 'Hay cambio, así que hay fem.'], ['hace que la corriente cambie de sentido', 'La sostiene, no la invierte.']],
      'Se opone a la disminución.'),
    C('au-inercia', 'autoinduccion', 2, '¿Con qué cantidad mecánica se suele comparar la inductancia?', 'Con la masa (inercia): se opone a los cambios de velocidad',
      [['Con la fricción', 'La fricción se opone al movimiento, no a su cambio: se parece más a la resistencia.'], ['Con la constante de un resorte', 'El resorte se parece más al capacitor.'], ['Con la gravedad', 'La comparación es con la inercia.']],
      'L se opone a cambios de I, como m a cambios de v.'),
    C('au-polaridad-sube', 'autoinduccion', 2, 'La corriente entra a un inductor por su terminal A, sale por B y va en aumento. ¿Qué terminal está a mayor potencial?', 'A',
      [['B', 'Si la corriente crece, el potencial baja al cruzar el inductor en su sentido.'], ['Los dos igual', 'Solo si la corriente fuera constante.'], ['Depende de la resistencia del circuito', 'El signo lo fija $-L\\,dI/dt$.']],
      '$\\Delta V = -L\\,dI/dt < 0$ de A a B.'),
    C('au-polaridad-baja', 'autoinduccion', 3, 'La corriente entra a un inductor por A, sale por B y va disminuyendo. ¿Qué terminal está a mayor potencial?', 'B',
      [['A', 'Con $dI/dt < 0$ el potencial sube al cruzar de A a B.'], ['Los dos igual', 'La corriente cambia: hay diferencia de potencial.'], ['Ninguno: el voltaje es cero porque la corriente baja', 'No es cero: $\\Delta V = -L\\,dI/dt$.']],
      '$\\Delta V = -L\\,dI/dt > 0$ de A a B.'),
    C('au-alambre', 'autoinduccion', 3, '¿Un alambre recto y largo tiene autoinductancia?', 'Sí, aunque muy pequeña: su corriente también produce un flujo propio',
      [['No, solo las bobinas la tienen', 'Cualquier circuito encierra flujo propio.'], ['No, porque es recto', 'Recto o no, su campo produce flujo.'], ['Sí, y es mayor que la de cualquier bobina', 'Es muy pequeña comparada con una bobina.']],
      'Todo circuito tiene algo de $L$.'),
    N('au-fem-simple', 'autoinduccion', 1, { L: [10, 500, 10], r: [2, 50, 2] },
      function (v) { return 'En un inductor de $' + v.L + '\\ \\text{mH}$ la corriente cambia a razón de $' + v.r + '\\ \\text{A/s}$. ¿Cuánto vale la fem autoinducida (en valor absoluto), en V?'; },
      function (v) { return v.L / 1000 * v.r; }, '$|\\varepsilon| = L\\,|dI/dt|$.',
      { unit: 'V', mistakes: { mH: function (v) { return v.L * v.r; } }, feedback: [{ when: 'mH', say: 'Pasa los mH a H.' }] },
      function (v, LM) { return Math.abs(IN(LM).emf(v.L / 1000, v.r)); }),
    N('au-dIdt', 'autoinduccion', 2, { L: [10, 500, 10], e: [1, 20, 1] },
      function (v) { return 'En un inductor de $' + v.L + '\\ \\text{mH}$ se mide una fem autoinducida de $' + v.e + '\\ \\text{V}$. ¿A qué ritmo cambia la corriente, en A/s?'; },
      function (v) { return v.e / (v.L / 1000); }, '$|dI/dt| = |\\varepsilon|/L$.', { unit: 'A/s' },
      function (v, LM) { return v.e / Math.abs(IN(LM).emf(v.L / 1000, 1)); }),
    N('au-apagar', 'autoinduccion', 2, { L: [50, 900, 50], I: [0.5, 5, 0.5], dt: [1, 10, 1] },
      function (v) { return 'Una bobina de $' + v.L + '\\ \\text{mH}$ lleva $' + fx(v.I, 1) + '\\ \\text{A}$ y un interruptor corta la corriente en $' + v.dt + '\\ \\text{ms}$ (uniformemente). ¿Qué fem promedio aparece, en V?'; },
      function (v) { return v.L / 1000 * v.I / (v.dt / 1000); }, '$|\\varepsilon| = L\\,\\Delta I/\\Delta t$.', { unit: 'V' },
      function (v, LM) { return Math.abs(IN(LM).emf(v.L / 1000, v.I / (v.dt / 1000))); }),
    N('au-tiempo', 'autoinduccion', 3, { L: [50, 500, 50], I: [0.5, 5, 0.5], e: [5, 50, 5] },
      function (v) { return 'Para que una bobina de $' + v.L + '\\ \\text{mH}$ que lleva $' + fx(v.I, 1) + '\\ \\text{A}$ no produzca más de $' + v.e + '\\ \\text{V}$ al apagarla, ¿en cuánto tiempo mínimo debe bajar la corriente a cero (uniformemente)? En ms.'; },
      function (v) { return v.L / 1000 * v.I / v.e * 1000; }, '$\\Delta t = L\\,\\Delta I/|\\varepsilon|$.', { unit: 'ms' },
      function (v, LM) { return v.I / (v.e / Math.abs(IN(LM).emf(v.L / 1000, 1))) * 1000; }),

    /* ======================= Inductancia: definición y unidades ======================= */
    C('in-def', 'inductancia', 1, 'La inductancia de una bobina se define como…', '$L = N\\Phi/I$: enlace de flujo por unidad de corriente',
      [['$L = I/(N\\Phi)$', 'Está invertida.'], ['$L = \\varepsilon I$', 'Eso tiene unidades de potencia.'], ['$L = \\Phi/N$', 'Falta la corriente.']],
      'Enlace de flujo entre corriente.'),
    C('in-henry', 'inductancia', 1, '¿Cuál es la unidad de la inductancia?', 'El henry, $1\\ \\text{H} = 1\\ \\text{V·s/A}$',
      [['El farad', 'El farad es de capacitancia.'], ['El weber', 'El weber es de flujo; el henry es Wb/A.'], ['El ohm', 'El ohm es V/A; el henry es V·s/A.']],
      '1 H = 1 Wb/A = 1 V·s/A.'),
    C('in-depende', 'inductancia', 1, 'La inductancia de una bobina depende de…', 'su geometría y del material de su núcleo',
      [['la corriente que lleva', 'El flujo es proporcional a $I$: el cociente no depende de $I$.'], ['el voltaje de la fuente', 'No depende de la fuente.'], ['qué tan rápido cambia la corriente', 'Eso cambia la fem, no $L$.']],
      'Como $C$, depende de la forma y el material.'),
    C('in-doble-I', 'inductancia', 1, 'Si duplicas la corriente en una bobina, su inductancia…', 'no cambia',
      [['se duplica', 'El flujo se duplica también: $L = N\\Phi/I$ queda igual.'], ['se reduce a la mitad', 'No depende de $I$.'], ['se cuadruplica', 'No depende de $I$.']],
      '$L$ es de la geometría.'),
    C('in-henry-grande', 'inductancia', 2, '¿Qué inductancia es más común en un inductor pequeño de aire de un circuito electrónico?', 'Del orden de microhenries o milihenries',
      [['Del orden de cientos de henries', 'Un henry ya es mucho para una bobina de aire.'], ['Exactamente 1 H siempre', 'Varía mucho según el diseño.'], ['Del orden de kilohenries', 'Sería enorme.']],
      'El henry es una unidad grande.'),
    C('in-equiv', 'inductancia', 2, '¿Cuál de estas combinaciones es equivalente a un henry?', '$\\text{Wb/A}$',
      [['$\\text{A/Wb}$', 'Está al revés.'], ['$\\text{V/A}$', 'Eso es un ohm.'], ['$\\text{T/A}$', 'Falta el área: $\\text{T·m}^2/\\text{A}$.']],
      '$L = N\\Phi/I$.'),
    C('in-ohm-s', 'inductancia', 3, '¿Cuál de estas también es una forma de escribir el henry?', '$\\Omega\\cdot\\text{s}$',
      [['$\\Omega/\\text{s}$', '$\\text{V·s/A} = (\\text{V/A})\\cdot\\text{s} = \\Omega\\cdot\\text{s}$.'], ['$\\text{F·s}$', 'El farad no entra aquí.'], ['$\\text{J·A}$', 'Eso no es un henry.']],
      'Por eso $L/R$ tiene unidades de tiempo (S14).'),
    C('in-capacitor', 'inductancia', 2, 'La inductancia es al flujo magnético lo que la capacitancia es a…', 'la carga eléctrica: $C = Q/V$ y $L = N\\Phi/I$',
      [['la corriente', 'La capacitancia relaciona carga y voltaje.'], ['la resistencia', 'La resistencia es otra cosa.'], ['la energía', 'Las dos guardan energía, pero se definen con $Q$ y con $N\\Phi$.']],
      'Las dos son constantes geométricas.'),
    N('in-desde-flujo', 'inductancia', 1, { N: [100, 1000, 100], phi: [10, 90, 10], I: [0.5, 5, 0.5] },
      function (v) { return 'Una bobina de $' + v.N + '$ vueltas lleva $' + fx(v.I, 1) + '\\ \\text{A}$ y cada vuelta atraviesa $' + v.phi + '\\ \\mu\\text{Wb}$. ¿Cuánto vale su inductancia, en mH?'; },
      function (v) { return v.N * v.phi * 1e-6 / v.I * 1000; }, '$L = N\\Phi/I$.',
      { unit: 'mH', mistakes: { noN: function (v) { return v.phi * 1e-6 / v.I * 1000; } }, feedback: [{ when: 'noN', say: 'Falta multiplicar por $N$: el enlace de flujo es $N\\Phi$.' }] },
      function (v, LM) { var s = IN(LM).state({ N: 1, r: 1, l: 1, Km: 1, kind: 'ramp', I0: v.I, k: 0 }, 0); return v.N * v.phi * 1e-6 / s.I * 1000; }),
    N('in-enlace', 'inductancia', 1, { L: [5, 200, 5], I: [0.5, 5, 0.5] },
      function (v) { return 'Una bobina de $' + v.L + '\\ \\text{mH}$ lleva $' + fx(v.I, 1) + '\\ \\text{A}$. ¿Cuánto vale su enlace de flujo $N\\Phi$, en mWb?'; },
      function (v) { return v.L * v.I; }, '$N\\Phi = LI$; mH × A = mWb.', { unit: 'mWb' },
      function (v, LM) { return v.L * IN(LM).current('ramp', { I0: v.I, k: 0 }, 1); }),
    N('in-flujo-vuelta', 'inductancia', 2, { L: [5, 200, 5], I: [0.5, 5, 0.5], N: [100, 1000, 100] },
      function (v) { return 'Una bobina de $' + v.N + '$ vueltas y $' + v.L + '\\ \\text{mH}$ lleva $' + fx(v.I, 1) + '\\ \\text{A}$. ¿Cuánto flujo atraviesa cada vuelta, en $\\mu\\text{Wb}$?'; },
      function (v) { return v.L / 1000 * v.I / v.N * 1e6; }, '$\\Phi = LI/N$.',
      { unit: 'μWb', mistakes: { noN: function (v) { return v.L / 1000 * v.I * 1e6; } }, feedback: [{ when: 'noN', say: 'Divide entre $N$: $LI$ es el flujo de todas las vueltas juntas.' }] },
      function (v, LM) { return v.L / 1000 * IN(LM).current('ramp', { I0: v.I, k: 0 }, 0) / v.N * 1e6; }),
    N('in-I', 'inductancia', 2, { L: [10, 400, 10], NPhi: [1, 20, 1] },
      function (v) { return 'El enlace de flujo de una bobina de $' + v.L + '\\ \\text{mH}$ es $' + v.NPhi + '\\ \\text{mWb}$. ¿Qué corriente lleva, en A?'; },
      function (v) { return v.NPhi / v.L; }, '$I = N\\Phi/L$.', { unit: 'A' },
      function (v, LM) { return v.NPhi * 1e-3 / Math.abs(IN(LM).emf(v.L / 1000, 1)); }),
    N('in-desde-fem', 'inductancia', 2, { e: [1, 30, 1], r: [10, 500, 10] },
      function (v) { return 'Cuando la corriente en una bobina cambia a $' + v.r + '\\ \\text{A/s}$, aparece una fem de $' + v.e + '\\ \\text{V}$. ¿Cuánto vale su inductancia, en mH?'; },
      function (v) { return v.e / v.r * 1000; }, '$L = |\\varepsilon|/|dI/dt|$.', { unit: 'mH' },
      function (v, LM) { return v.e / Math.abs(IN(LM).emf(1, v.r)) * 1000; }),

    /* ======================= Solenoide ======================= */
    C('so-formula', 'solenoide', 1, 'La inductancia de un solenoide largo de aire es…', '$L = \\mu_0N^2A/\\ell$',
      [['$L = \\mu_0NA/\\ell$', 'Falta elevar $N$ al cuadrado.'], ['$L = \\mu_0N^2\\ell/A$', '$A$ y $\\ell$ están al revés.'], ['$L = \\mu_0NI/\\ell$', 'Eso es el campo $B$, no la inductancia.']],
      '$L = N\\Phi/I$ con $B = \\mu_0NI/\\ell$ y $\\Phi = BA$.'),
    C('so-N2', 'solenoide', 2, '¿Por qué la inductancia de un solenoide va con $N^2$?', 'Porque el campo crece con $N$ y ese campo atraviesa las $N$ vueltas',
      [['Porque cada vuelta tiene dos lados', 'La razón es el campo y el número de vueltas que lo atraviesan.'], ['Porque el área crece con $N$', 'El área es la de una vuelta.'], ['Porque la corriente crece con $N$', 'La corriente es la misma.']],
      'Una $N$ por el campo, otra por el enlace.'),
    C('so-doble-N', 'solenoide', 1, 'Si duplicas las vueltas de un solenoide sin cambiar su largo, su inductancia…', 'se multiplica por 4',
      [['se duplica', 'Es $N^2$.'], ['no cambia', 'Más vueltas, más inductancia.'], ['se reduce a la mitad', 'Crece.']],
      '$(2N)^2 = 4N^2$.'),
    C('so-doble-l', 'solenoide', 2, 'Estiras un solenoide al doble de largo sin cambiar sus vueltas ni su radio. Su inductancia…', 'se reduce a la mitad',
      [['se duplica', '$\\ell$ está en el denominador.'], ['no cambia', 'Las vueltas quedan más separadas y el campo baja.'], ['se reduce a la cuarta parte', 'Es $1/\\ell$, no $1/\\ell^2$.']],
      '$L \\propto 1/\\ell$.'),
    C('so-doble-r', 'solenoide', 2, 'Si duplicas el radio de un solenoide (mismo $N$ y $\\ell$), su inductancia…', 'se multiplica por 4',
      [['se duplica', 'El área va con $r^2$.'], ['no cambia', 'Más área, más flujo.'], ['se reduce a la mitad', 'Crece.']],
      '$A = \\pi r^2$.'),
    C('so-n-fijo', 'solenoide', 3, 'Dos solenoides tienen el mismo radio y la misma densidad de vueltas $n = N/\\ell$, pero uno es el doble de largo. Su inductancia…', 'es el doble en el más largo',
      [['es la misma', '$L = \\mu_0n^2A\\ell$: con $n$ fija, $L$ crece con $\\ell$.'], ['es la mitad en el más largo', 'Con $n$ fija, más largo es más inductancia.'], ['es 4 veces en el más largo', 'Es lineal en $\\ell$ con $n$ fija.']],
      '$L = \\mu_0n^2A\\ell$.'),
    C('so-bordes', 'solenoide', 3, 'En un solenoide corto, la inductancia real comparada con $\\mu_0N^2A/\\ell$ es…', 'un poco menor, porque el campo se abre en los extremos',
      [['un poco mayor, porque el campo se concentra en los extremos', 'En los extremos el campo es menor que en el centro.'], ['exactamente igual', 'La fórmula supone un solenoide largo.'], ['cero', 'Sigue teniendo inductancia.']],
      'El campo uniforme es una idealización.'),
    N('so-L', 'solenoide', 1, { N: [100, 1000, 50], r: [0.5, 3, 0.5], l: [5, 40, 5] },
      function (v) { return 'Un solenoide de aire tiene $' + v.N + '$ vueltas, $' + fx(v.r, 1) + '\\ \\text{cm}$ de radio y $' + v.l + '\\ \\text{cm}$ de largo. ¿Cuánto vale su inductancia, en mH?'; },
      function (v) { return Lsol(v.N, v.r, v.l, 1) * 1000; }, '$L = \\mu_0N^2A/\\ell$.',
      { unit: 'mH', mistakes: { noSquare: function (v) { return Lsol(v.N, v.r, v.l, 1) * 1000 / v.N; } }, feedback: [{ when: 'noSquare', say: 'Es $N^2$.' }] },
      function (v, LM) { return IN(LM).ideal(v.N, v.r, v.l, 1) * 1000; }),
    N('so-L-area', 'solenoide', 1, { N: [100, 800, 100], A: [1, 10, 1], l: [5, 40, 5] },
      function (v) { return 'Un solenoide de aire de $' + v.N + '$ vueltas tiene una sección de $' + v.A + '\\ \\text{cm}^2$ y $' + v.l + '\\ \\text{cm}$ de largo. ¿Cuánto vale su inductancia, en mH?'; },
      function (v) { return MU0 * v.N * v.N * v.A * 1e-4 / (v.l / 100) * 1000; }, '$L = \\mu_0N^2A/\\ell$ con $A$ en m².',
      { unit: 'mH', mistakes: { cm2: function (v) { return MU0 * v.N * v.N * v.A / (v.l / 100) * 1000; } }, feedback: [{ when: 'cm2', say: 'El área va en m²: $1\\ \\text{cm}^2 = 10^{-4}\\ \\text{m}^2$.' }] },
      function (v, LM) { return IN(LM).ideal(v.N, Math.sqrt(v.A / Math.PI), v.l, 1) * 1000; }),
    N('so-L-uH', 'solenoide', 2, { N: [20, 200, 10], r: [0.2, 1, 0.1], l: [1, 10, 1] },
      function (v) { return 'Una bobina de aire de $' + v.N + '$ vueltas, $' + fx(v.r, 1) + '\\ \\text{cm}$ de radio y $' + v.l + '\\ \\text{cm}$ de largo se usa en un radio. ¿Cuánto vale su inductancia, en $\\mu\\text{H}$?'; },
      function (v) { return Lsol(v.N, v.r, v.l, 1) * 1e6; }, '$L = \\mu_0N^2A/\\ell$; $1\\ \\mu\\text{H} = 10^{-6}\\ \\text{H}$.',
      { unit: 'μH', mistakes: { cmLen: function (v) { return Lsol(v.N, v.r, v.l, 1) * 1e6 / 100; } }, feedback: [{ when: 'cmLen', say: 'El largo va en metros.' }] },
      function (v, LM) { return IN(LM).ideal(v.N, v.r, v.l, 1) * 1e6; }),
    N('so-n', 'solenoide', 2, { n: [500, 5000, 500], r: [0.5, 2, 0.5], l: [10, 50, 10] },
      function (v) { return 'Un solenoide de aire de $' + v.l + '\\ \\text{cm}$ de largo y $' + fx(v.r, 1) + '\\ \\text{cm}$ de radio tiene $' + v.n + '$ vueltas por metro. ¿Cuánto vale su inductancia, en mH?'; },
      function (v) { return MU0 * v.n * v.n * area(v.r) * (v.l / 100) * 1000; }, '$N = n\\ell$, así que $L = \\mu_0n^2A\\ell$.',
      { unit: 'mH', mistakes: { asN: function (v) { return MU0 * v.n * v.n * area(v.r) / (v.l / 100) * 1000; } }, feedback: [{ when: 'asN', say: 'Te dieron vueltas por metro: el total es $N = n\\ell$.' }] },
      function (v, LM) { return IN(LM).ideal(v.n * v.l / 100, v.r, v.l, 1) * 1000; }),
    N('so-N', 'solenoide', 2, { L: [1, 50, 1], r: [0.5, 3, 0.5], l: [5, 40, 5] },
      function (v) { return '¿Cuántas vueltas necesita un solenoide de aire de $' + fx(v.r, 1) + '\\ \\text{cm}$ de radio y $' + v.l + '\\ \\text{cm}$ de largo para tener $' + v.L + '\\ \\text{mH}$? (Sin redondear.)'; },
      function (v) { return Math.sqrt(v.L / 1000 * (v.l / 100) / (MU0 * area(v.r))); }, '$N = \\sqrt{L\\ell/(\\mu_0A)}$.',
      { unit: '', mistakes: { noSqrt: function (v) { return v.L / 1000 * (v.l / 100) / (MU0 * area(v.r)); } }, feedback: [{ when: 'noSqrt', say: 'Eso es $N^2$; saca la raíz.' }] },
      function (v, LM) { return IN(LM).turnsFor(v.L / 1000, v.r, v.l, 1); }),
    N('so-l', 'solenoide', 3, { L: [1, 20, 1], N: [200, 1000, 100], r: [0.5, 2, 0.5] },
      function (v) { return 'Un solenoide de aire de $' + v.N + '$ vueltas y $' + fx(v.r, 1) + '\\ \\text{cm}$ de radio debe tener $' + v.L + '\\ \\text{mH}$. ¿Qué largo debe tener, en cm?'; },
      function (v) { return MU0 * v.N * v.N * area(v.r) / (v.L / 1000) * 100; }, '$\\ell = \\mu_0N^2A/L$.',
      { unit: 'cm', where: function (v) { var l = MU0 * v.N * v.N * area(v.r) / (v.L / 1000) * 100; return l >= 1 && l <= 200; } },
      function (v, LM) { return IN(LM).ideal(v.N, v.r, 100, 1) / (v.L / 1000) * 100; }),
    N('so-B', 'solenoide', 1, { N: [100, 1000, 100], l: [10, 50, 5], I: [0.5, 5, 0.5] },
      function (v) { return 'Un solenoide de $' + v.N + '$ vueltas y $' + v.l + '\\ \\text{cm}$ de largo lleva $' + fx(v.I, 1) + '\\ \\text{A}$. ¿Cuánto vale el campo adentro, en mT?'; },
      function (v) { return MU0 * v.N * v.I / (v.l / 100) * 1000; }, '$B = \\mu_0NI/\\ell$.', { unit: 'mT' },
      function (v, LM) { return IN(LM).field(v.N, v.l, v.I, 1) * 1000; }),
    N('so-razon', 'solenoide', 3, { a: [2, 5, 1], b: [2, 5, 1] },
      function (v) { return 'El solenoide A tiene $' + v.a + '$ veces más vueltas que el B y es $' + v.b + '$ veces más largo; los dos tienen el mismo radio. ¿Cuántas veces es mayor la inductancia de A que la de B?'; },
      function (v) { return v.a * v.a / v.b; }, '$L \\propto N^2/\\ell$.',
      { unit: '', mistakes: { lin: function (v) { return v.a / v.b; } }, feedback: [{ when: 'lin', say: 'Es $N^2$: el cociente es $a^2/b$.' }] },
      function (v, LM) { return IN(LM).ideal(100 * v.a, 1, 10 * v.b, 1) / IN(LM).ideal(100, 1, 10, 1); }),

    /* ======================= Fem autoinducida ======================= */
    C('fe-formula', 'fem', 1, 'La fem autoinducida en una bobina de inductancia $L$ es…', '$\\varepsilon = -L\\,dI/dt$',
      [['$\\varepsilon = -LI$', 'Falta la derivada: importa cómo cambia $I$.'], ['$\\varepsilon = -L/I$', 'No es un cociente con $I$.'], ['$\\varepsilon = -I\\,dL/dt$', '$L$ es constante; lo que cambia es $I$.']],
      'Faraday con $N\\Phi = LI$.'),
    C('fe-grafica', 'fem', 2, 'La corriente en un inductor crece en línea recta con el tiempo. La fem autoinducida…', 'es constante',
      [['crece en línea recta', 'Va con la pendiente, que es constante.'], ['es cero', 'La corriente cambia: hay fem.'], ['decrece exponencialmente', 'Con pendiente constante, la fem es constante.']],
      '$dI/dt$ constante.'),
    C('fe-pico', 'fem', 2, 'Por un inductor pasa $I = I_m\\sin\\omega t$. ¿Cuándo es máxima la fem autoinducida?', 'Cuando la corriente pasa por cero',
      [['Cuando la corriente es máxima', 'Ahí la pendiente de $I(t)$ es cero.'], ['Siempre vale lo mismo', 'Va con $\\cos\\omega t$.'], ['Nunca: la fem es cero en alterna', 'La corriente cambia todo el tiempo.']],
      '$\\varepsilon \\propto \\cos\\omega t$.'),
    C('fe-frecuencia', 'fem', 2, 'Con la misma amplitud de corriente, si duplicas la frecuencia de la corriente alterna en un inductor, la fem máxima…', 'se duplica',
      [['no cambia', '$|\\varepsilon|_{\\max} = LI_m\\omega$ crece con $\\omega$.'], ['se reduce a la mitad', 'Crece con la frecuencia.'], ['se cuadruplica', 'Es lineal en $\\omega$.']],
      'Corriente más rápida, más fem.'),
    C('fe-signo', 'fem', 2, 'La corriente en un inductor baja de 3 A a 1 A. Durante ese cambio, la fem autoinducida es…', 'positiva: empuja a favor de la corriente',
      [['negativa: empuja en contra de la corriente', 'Eso sería si la corriente subiera.'], ['cero', 'La corriente cambia.'], ['igual a $L$ por 2 A', 'Falta dividir entre el tiempo.']],
      '$dI/dt < 0$ → $\\varepsilon = -L\\,dI/dt > 0$.'),
    N('fe-rampa', 'fem', 1, { L: [5, 200, 5], dI: [0.5, 5, 0.5], dt: [1, 20, 1] },
      function (v) { return 'En un inductor de $' + v.L + '\\ \\text{mH}$ la corriente aumenta uniformemente $' + fx(v.dI, 1) + '\\ \\text{A}$ en $' + v.dt + '\\ \\text{ms}$. ¿Cuánto vale $|\\varepsilon|$, en V?'; },
      function (v) { return v.L / 1000 * v.dI / (v.dt / 1000); }, '$|\\varepsilon| = L\\,\\Delta I/\\Delta t$.',
      { unit: 'V', mistakes: { useI: function (v) { return v.L / 1000 * v.dI; }, ms: function (v) { return v.L / 1000 * v.dI / v.dt; } }, feedback: [{ when: 'useI', say: 'Divide entre el tiempo: la fem va con $dI/dt$.' }, { when: 'ms', say: 'El tiempo va en segundos.' }] },
      function (v, LM) { return Math.abs(IN(LM).emf(v.L / 1000, v.dI / (v.dt / 1000))); }),
    N('fe-sol-rampa', 'fem', 2, { N: [200, 1000, 100], r: [0.5, 2, 0.5], l: [10, 40, 5], k: [10, 200, 10] },
      function (v) { return 'Por un solenoide de aire de $' + v.N + '$ vueltas, $' + fx(v.r, 1) + '\\ \\text{cm}$ de radio y $' + v.l + '\\ \\text{cm}$ de largo, la corriente crece a $' + v.k + '\\ \\text{A/s}$. ¿Cuánto vale $|\\varepsilon|$, en mV?'; },
      function (v) { return Lsol(v.N, v.r, v.l, 1) * v.k * 1000; }, 'Primero $L$, luego $|\\varepsilon| = L\\,dI/dt$.',
      { unit: 'mV', mistakes: { noSquare: function (v) { return Lsol(v.N, v.r, v.l, 1) / v.N * v.k * 1000; } }, feedback: [{ when: 'noSquare', say: 'En $L$ va $N^2$.' }] },
      function (v, LM) { return Math.abs(IN(LM).state({ N: v.N, r: v.r, l: v.l, Km: 1, kind: 'ramp', I0: 0, k: v.k }, 0).emf) * 1000; }),
    N('fe-alterna', 'fem', 2, { L: [10, 500, 10], Im: [0.1, 2, 0.1], f: [50, 1000, 50] },
      function (v) { return 'Por un inductor de $' + v.L + '\\ \\text{mH}$ pasa una corriente alterna de amplitud $' + fx(v.Im, 1) + '\\ \\text{A}$ y $' + v.f + '\\ \\text{Hz}$. ¿Cuánto vale la fem máxima, en V?'; },
      function (v) { return v.L / 1000 * v.Im * TAU * v.f; }, '$|\\varepsilon|_{\\max} = LI_m\\omega$.',
      { unit: 'V', mistakes: { f: function (v) { return v.L / 1000 * v.Im * v.f; } }, feedback: [{ when: 'f', say: 'Usa $\\omega = 2\\pi f$.' }] },
      function (v, LM) { var L = v.L / 1000; return Math.abs(IN(LM).emf(L, IN(LM).dIdt('sine', { Im: v.Im, f: v.f }, 0))); }),
    N('fe-alterna-t', 'fem', 3, { L: [10, 200, 10], Im: [0.5, 2, 0.5], f: [50, 60, 10], t: [1, 7, 1] },
      function (v) { return 'Por un inductor de $' + v.L + '\\ \\text{mH}$ pasa $I = ' + fx(v.Im, 1) + '\\sin(2\\pi\\cdot ' + v.f + '\\,t)$ A. ¿Cuánto vale la fem autoinducida $\\varepsilon = -L\\,dI/dt$ en $t = ' + v.t + '\\ \\text{ms}$, en V? (Puede ser negativa.)'; },
      function (v) { var w = TAU * v.f; return -v.L / 1000 * v.Im * w * Math.cos(w * v.t / 1000); }, '$\\varepsilon = -LI_m\\omega\\cos\\omega t$, con el ángulo en radianes.',
      { unit: 'V', where: function (v) { return Math.abs(Math.cos(TAU * v.f * v.t / 1000)) > 0.15; }, mistakes: { sine: function (v) { var w = TAU * v.f; return -v.L / 1000 * v.Im * w * Math.sin(w * v.t / 1000); } }, feedback: [{ when: 'sine', say: 'La derivada de $\\sin\\omega t$ es $\\omega\\cos\\omega t$.' }] },
      function (v, LM) { return IN(LM).state({ N: 1, r: 1, l: 1, Km: 1, kind: 'sine', Im: v.Im, f: v.f }, v.t / 1000).emf / IN(LM).ideal(1, 1, 1, 1) * v.L / 1000; }),
    N('fe-L-sol', 'fem', 3, { N: [200, 800, 100], r: [1, 3, 0.5], l: [10, 40, 5], e: [1, 10, 1] },
      function (v) { return 'Por un solenoide de aire de $' + v.N + '$ vueltas, $' + fx(v.r, 1) + '\\ \\text{cm}$ de radio y $' + v.l + '\\ \\text{cm}$ de largo, ¿a qué ritmo debe cambiar la corriente para que la fem autoinducida sea de $' + v.e + '\\ \\text{V}$? En A/s.'; },
      function (v) { return v.e / Lsol(v.N, v.r, v.l, 1); }, '$dI/dt = |\\varepsilon|/L$.', { unit: 'A/s' },
      function (v, LM) { return v.e / IN(LM).ideal(v.N, v.r, v.l, 1); }),
    N('fe-cambio-I', 'fem', 2, { L: [10, 400, 10], e: [1, 20, 1], dt: [1, 20, 1] },
      function (v) { return 'Un inductor de $' + v.L + '\\ \\text{mH}$ tiene una fem autoinducida constante de $' + v.e + '\\ \\text{V}$ durante $' + v.dt + '\\ \\text{ms}$. ¿Cuánto cambió su corriente en ese tiempo, en A?'; },
      function (v) { return v.e * (v.dt / 1000) / (v.L / 1000); }, '$\\Delta I = |\\varepsilon|\\,\\Delta t/L$.', { unit: 'A' },
      function (v, LM) { return v.e / Math.abs(IN(LM).emf(v.L / 1000, 1)) * v.dt / 1000; }),
    N('fe-doble', 'fem', 2, { L1: [10, 100, 10], k: [2, 5, 1] },
      function (v) { return 'Dos inductores, de $' + v.L1 + '\\ \\text{mH}$ y de $' + (v.k * v.L1) + '\\ \\text{mH}$, tienen la misma $dI/dt$. ¿Cuántas veces es mayor la fem del segundo?'; },
      function (v) { return v.k; }, 'La fem es proporcional a $L$.', { unit: '' },
      function (v, LM) { return IN(LM).emf(v.k * v.L1, 1) / IN(LM).emf(v.L1, 1); }),

    /* ======================= Núcleo ======================= */
    C('nu-hierro', 'nucleo', 1, 'Si metes un núcleo de hierro dentro de un solenoide, su inductancia…', 'aumenta mucho',
      [['disminuye', 'El hierro multiplica el campo y el flujo.'], ['no cambia', 'El material sí cuenta.'], ['se vuelve cero', 'Al contrario.']],
      '$L = K_m\\mu_0N^2A/\\ell$ con $K_m$ grande.'),
    C('nu-km', 'nucleo', 1, 'En $L = K_m\\mu_0N^2A/\\ell$, ¿qué es $K_m$?', 'La permeabilidad relativa del material del núcleo',
      [['El número de vueltas por metro', 'Eso es $n$.'], ['La constante de Coulomb', 'Esa es $k$, de electrostática.'], ['La resistencia del alambre', 'No entra en $L$.']],
      '$K_m = 1$ en el aire.'),
    C('nu-aire', 'nucleo', 1, '¿Cuánto vale $K_m$ para un solenoide sin núcleo (aire o vacío)?', 'Prácticamente 1',
      [['Cero', 'Con $K_m = 0$ no habría inductancia.'], ['1000', 'Ese es un valor típico de hierro.'], ['$\\mu_0$', '$\\mu_0$ ya está aparte en la fórmula.']],
      'El aire casi no modifica el campo.'),
    C('nu-por-que', 'nucleo', 2, '¿Por qué un núcleo ferromagnético aumenta la inductancia?', 'Porque sus dominios se alinean con el campo y lo refuerzan, aumentando el flujo',
      [['Porque reduce la resistencia del alambre', 'El núcleo no toca el alambre.'], ['Porque guarda carga eléctrica', 'Es un efecto magnético.'], ['Porque hace más largo el solenoide', 'El largo no cambia.']],
      'El material se magnetiza.'),
    C('nu-transformador', 'nucleo', 2, '¿Por qué los transformadores tienen un núcleo de hierro?', 'Para concentrar y aumentar el flujo, de modo que casi todo el flujo de una bobina pase por la otra',
      [['Para que sean más pesados y estables', 'El hierro tiene una función magnética.'], ['Para aislar las bobinas', 'El aislamiento lo da el barniz del alambre.'], ['Para conducir la corriente entre las bobinas', 'No hay corriente entre bobinas: se acoplan por flujo.']],
      'El hierro guía el flujo.'),
    C('nu-menos-vueltas', 'nucleo', 2, 'Con un núcleo de $K_m = 100$, ¿cuántas veces menos vueltas necesitas para la misma inductancia que sin núcleo?', '10 veces menos',
      [['100 veces menos', '$L \\propto K_mN^2$: basta con $N$ dividido entre $\\sqrt{100}$.'], ['Las mismas', 'El núcleo multiplica $L$.'], ['50 veces menos', 'Es $\\sqrt{K_m}$.']],
      '$N \\propto 1/\\sqrt{K_m}$.'),
    C('nu-diamagnetico', 'nucleo', 3, 'Si el núcleo fuera de un material diamagnético (como el cobre, $K_m$ ligeramente menor que 1), la inductancia…', 'bajaría muy poco',
      [['subiría mucho', 'Solo los ferromagnéticos la aumentan mucho.'], ['se volvería cero', 'El efecto es minúsculo.'], ['cambiaría de signo', '$K_m$ sigue siendo positiva y cercana a 1.']],
      '$K_m \\approx 1 - 10^{-5}$.'),
    C('nu-saturacion', 'nucleo', 3, 'Con corrientes muy grandes, un núcleo de hierro deja de reforzar el campo como al principio. ¿Qué le pasa a la inductancia?', 'Disminuye, porque el núcleo se satura',
      [['Aumenta sin límite', 'Cuando todos los dominios ya están alineados, el núcleo ya no ayuda más.'], ['Se queda exactamente igual', 'Con saturación $K_m$ efectiva baja.'], ['Se vuelve negativa', 'No se vuelve negativa.']],
      'La saturación limita al hierro.'),
    N('nu-L', 'nucleo', 1, { L0: [1, 20, 1], Km: [50, 1000, 50] },
      function (v) { return 'Un solenoide de aire tiene $' + v.L0 + '\\ \\text{mH}$. Si lo llenas con un núcleo de $K_m = ' + v.Km + '$, ¿cuánto vale su inductancia, en mH?'; },
      function (v) { return v.L0 * v.Km; }, '$L = K_mL_0$.', { unit: 'mH' },
      function (v, LM) { return v.L0 * IN(LM).ideal(10, 1, 10, v.Km) / IN(LM).ideal(10, 1, 10, 1); }),
    N('nu-sol', 'nucleo', 2, { N: [50, 500, 50], r: [0.5, 2, 0.5], l: [5, 20, 5], Km: [100, 1000, 100] },
      function (v) { return 'Un solenoide de $' + v.N + '$ vueltas, $' + fx(v.r, 1) + '\\ \\text{cm}$ de radio y $' + v.l + '\\ \\text{cm}$ de largo tiene un núcleo con $K_m = ' + v.Km + '$. ¿Cuánto vale su inductancia, en mH?'; },
      function (v) { return Lsol(v.N, v.r, v.l, v.Km) * 1000; }, '$L = K_m\\mu_0N^2A/\\ell$.',
      { unit: 'mH', mistakes: { noKm: function (v) { return Lsol(v.N, v.r, v.l, 1) * 1000; } }, feedback: [{ when: 'noKm', say: 'Falta multiplicar por $K_m$.' }] },
      function (v, LM) { return IN(LM).ideal(v.N, v.r, v.l, v.Km) * 1000; }),
    N('nu-N', 'nucleo', 2, { L: [10, 500, 10], r: [0.5, 2, 0.5], l: [5, 20, 5], Km: [100, 1000, 100] },
      function (v) { return '¿Cuántas vueltas necesita un solenoide con núcleo de $K_m = ' + v.Km + '$, $' + fx(v.r, 1) + '\\ \\text{cm}$ de radio y $' + v.l + '\\ \\text{cm}$ de largo para tener $' + v.L + '\\ \\text{mH}$? (Sin redondear.)'; },
      function (v) { return Math.sqrt(v.L / 1000 * (v.l / 100) / (v.Km * MU0 * area(v.r))); }, '$N = \\sqrt{L\\ell/(K_m\\mu_0A)}$.',
      { unit: '', mistakes: { noKm: function (v) { return Math.sqrt(v.L / 1000 * (v.l / 100) / (MU0 * area(v.r))); } }, feedback: [{ when: 'noKm', say: 'Olvidaste el núcleo: divide entre $K_m$ dentro de la raíz.' }] },
      function (v, LM) { return IN(LM).turnsFor(v.L / 1000, v.r, v.l, v.Km); }),
    N('nu-Km', 'nucleo', 2, { L0: [1, 10, 1], k: [50, 900, 50] },
      function (v) { return 'Un solenoide de aire tiene $' + v.L0 + '\\ \\text{mH}$; con un núcleo, su inductancia sube a $' + (v.L0 * v.k) + '\\ \\text{mH}$. ¿Cuánto vale $K_m$ del núcleo?'; },
      function (v) { return v.k; }, '$K_m = L/L_0$.', { unit: '' },
      function (v, LM) { return IN(LM).ideal(10, 1, 10, v.k) / IN(LM).ideal(10, 1, 10, 1); }),
    N('nu-B', 'nucleo', 2, { N: [100, 500, 100], l: [10, 30, 5], I: [0.1, 1, 0.1], Km: [100, 1000, 100] },
      function (v) { return 'Un solenoide de $' + v.N + '$ vueltas y $' + v.l + '\\ \\text{cm}$ de largo con núcleo de $K_m = ' + v.Km + '$ lleva $' + fx(v.I, 1) + '\\ \\text{A}$. ¿Cuánto vale el campo en el núcleo, en T?'; },
      function (v) { return v.Km * MU0 * v.N * v.I / (v.l / 100); }, '$B = K_m\\mu_0NI/\\ell$.',
      { unit: 'T', mistakes: { noKm: function (v) { return MU0 * v.N * v.I / (v.l / 100); } }, feedback: [{ when: 'noKm', say: 'El núcleo multiplica el campo por $K_m$.' }] },
      function (v, LM) { return IN(LM).field(v.N, v.l, v.I, v.Km); }),

    /* ======================= Más: autoinducción ======================= */
    C('au-cuando', 'autoinduccion', 1, '¿En cuál de estos casos hay fem autoinducida en una bobina?', 'Cuando su corriente aumenta',
      [['Cuando lleva una corriente constante grande', 'Sin cambio de corriente no hay fem.'], ['Cuando está desconectada y sin corriente', 'No hay corriente ni cambio.'], ['Cuando hay un imán quieto cerca', 'Eso no cambia el flujo.']],
      'Hace falta que $I$ cambie.'),
    C('au-faraday', 'autoinduccion', 1, 'La autoinducción es un caso particular de…', 'la ley de Faraday, con el flujo producido por la propia corriente',
      [['la ley de Coulomb', 'Coulomb es de cargas en reposo.'], ['la ley de Ohm', 'Ohm relaciona $V$, $I$ y $R$.'], ['la ley de Gauss', 'Gauss es de flujo eléctrico en superficies cerradas.']],
      'El flujo es el propio.'),
    C('au-largo', 'autoinduccion', 2, 'Mucho tiempo después de conectar una bobina ideal (sin resistencia) a una pila, la bobina se comporta como…', 'un alambre, sin voltaje entre sus extremos',
      [['un circuito abierto', 'Eso le pasa a un capacitor cargado.'], ['una resistencia muy grande', 'Una bobina ideal no tiene resistencia.'], ['una pila en contra', 'Solo mientras la corriente cambia.']],
      'Con $I$ constante, $\\varepsilon = 0$.'),
    N('au-baja', 'autoinduccion', 2, { L: [10, 500, 10], I1: [3, 6, 0.5], I2: [0.5, 2.5, 0.5], dt: [1, 20, 1] },
      function (v) { return 'En un inductor de $' + v.L + '\\ \\text{mH}$ la corriente baja uniformemente de $' + fx(v.I1, 1) + '\\ \\text{A}$ a $' + fx(v.I2, 1) + '\\ \\text{A}$ en $' + v.dt + '\\ \\text{ms}$. ¿Cuánto vale $|\\varepsilon|$, en V?'; },
      function (v) { return v.L / 1000 * (v.I1 - v.I2) / (v.dt / 1000); }, '$|\\varepsilon| = L\\,|\\Delta I|/\\Delta t$.',
      { unit: 'V', mistakes: { useI1: function (v) { return v.L / 1000 * v.I1 / (v.dt / 1000); } }, feedback: [{ when: 'useI1', say: 'Usa el cambio de corriente, $I_1 - I_2$.' }] },
      function (v, LM) { return Math.abs(IN(LM).emf(v.L / 1000, (v.I2 - v.I1) / (v.dt / 1000))); }),
    C('au-invierte', 'autoinduccion', 2, 'La corriente en un inductor se invierte rápidamente, de $+2\\ \\text{A}$ a $-2\\ \\text{A}$. Durante el cambio, la fem autoinducida…', 'es grande y empuja en el sentido de la corriente original',
      [['es cero, porque la corriente promedio es cero', 'Importa el cambio, $\\Delta I = -4\\ \\text{A}$.'], ['empuja en el sentido de la corriente nueva', 'Se opone al cambio: favorece el sentido original.'], ['es pequeña, porque la corriente termina igual de grande', 'El cambio es de 4 A en poco tiempo: es grande.']],
      'Se opone al cambio.'),
    C('au-diodo', 'autoinduccion', 3, 'En la bobina de un relé se pone un diodo en paralelo. ¿Para qué?', 'Para dar un camino a la corriente al apagar y evitar la fem enorme de $L\\,dI/dt$',
      [['Para que la bobina gaste menos energía al encender', 'Al encender el diodo no conduce.'], ['Para aumentar la inductancia', 'El diodo no cambia $L$.'], ['Para que la corriente suba más rápido', 'Actúa al apagar.']],
      'Así la corriente decae poco a poco.'),
    N('au-chispa-kV', 'autoinduccion', 3, { L: [100, 900, 100], I: [1, 5, 0.5], dt: [10, 100, 10] },
      function (v) { return 'Una bobina de $' + v.L + '\\ \\text{mH}$ lleva $' + fx(v.I, 1) + '\\ \\text{A}$ y un contacto la corta en $' + v.dt + '\\ \\mu\\text{s}$. ¿Qué fem promedio aparece, en kV?'; },
      function (v) { return v.L / 1000 * v.I / (v.dt * 1e-6) / 1000; }, '$|\\varepsilon| = L\\,I/\\Delta t$ con $\\Delta t$ en segundos.',
      { unit: 'kV', mistakes: { ms: function (v) { return v.L / 1000 * v.I / (v.dt * 1e-3) / 1000; } }, feedback: [{ when: 'ms', say: 'Son microsegundos: $10^{-6}\\ \\text{s}$.' }] },
      function (v, LM) { return Math.abs(IN(LM).emf(v.L / 1000, v.I / (v.dt * 1e-6))) / 1000; }),

    /* ======================= Más: inductancia ======================= */
    C('in-proporcional', 'inductancia', 1, 'El flujo propio que atraviesa una bobina es…', 'proporcional a su corriente',
      [['independiente de su corriente', 'El campo lo produce la corriente.'], ['proporcional al cuadrado de su corriente', 'Es lineal: $N\\Phi = LI$.'], ['inversamente proporcional a su corriente', 'Más corriente, más flujo.']],
      '$N\\Phi = LI$.'),
    N('in-simple', 'inductancia', 1, { NPhi: [1, 30, 1], I: [0.5, 5, 0.5] },
      function (v) { return 'Una bobina con $' + fx(v.I, 1) + '\\ \\text{A}$ tiene un enlace de flujo de $' + v.NPhi + '\\ \\text{mWb}$. ¿Cuánto vale su inductancia, en mH?'; },
      function (v) { return v.NPhi / v.I; }, '$L = N\\Phi/I$; mWb/A = mH.', { unit: 'mH' },
      function (v, LM) { return v.NPhi / IN(LM).current('ramp', { I0: v.I, k: 0 }, 0); }),
    N('in-cambio-enlace', 'inductancia', 2, { L: [10, 400, 10], dI: [0.5, 5, 0.5] },
      function (v) { return 'La corriente en una bobina de $' + v.L + '\\ \\text{mH}$ aumenta $' + fx(v.dI, 1) + '\\ \\text{A}$. ¿Cuánto aumenta su enlace de flujo, en mWb?'; },
      function (v) { return v.L * v.dI; }, '$\\Delta(N\\Phi) = L\\,\\Delta I$.', { unit: 'mWb' },
      function (v, LM) { return Math.abs(IN(LM).emf(v.L, v.dI)); }),
    C('in-mayor', 'inductancia', 2, 'Dos bobinas llevan la misma corriente. La de mayor inductancia…', 'tiene mayor enlace de flujo',
      [['tiene menor enlace de flujo', '$N\\Phi = LI$: con la misma $I$, más $L$ es más flujo.'], ['tiene más resistencia', '$L$ no es resistencia.'], ['tiene menos vueltas', 'No necesariamente; depende de la geometría.']],
      '$N\\Phi = LI$.'),
    N('in-rampa', 'inductancia', 2, { e: [1, 20, 1], t: [1, 20, 1], I: [0.5, 5, 0.5] },
      function (v) { return 'La corriente en una bobina sube en línea recta de $0$ a $' + fx(v.I, 1) + '\\ \\text{A}$ en $' + v.t + '\\ \\text{ms}$ y mientras tanto la fem autoinducida mide $' + v.e + '\\ \\text{V}$. ¿Cuánto vale $L$, en mH?'; },
      function (v) { return v.e * v.t / v.I; }, '$L = |\\varepsilon|\\,\\Delta t/\\Delta I$; V·ms/A = mH.',
      { unit: 'mH', mistakes: { noT: function (v) { return v.e / v.I * 1000; } }, feedback: [{ when: 'noT', say: 'Usaste $\\varepsilon/I$. Es $\\varepsilon$ entre $dI/dt$: $L = \\varepsilon\\,\\Delta t/\\Delta I$.' }] },
      function (v, LM) { return v.e / Math.abs(IN(LM).emf(1, v.I / (v.t / 1000))) * 1000; }),
    C('in-unidades', 'inductancia', 2, 'Un compañero escribe la inductancia en V/A. ¿Está bien?', 'No: V/A es un ohm; el henry es V·s/A',
      [['Sí: V/A es el henry', 'V/A es el ohm.'], ['Sí, si la corriente es directa', 'Las unidades no dependen de eso.'], ['No: el henry es A/V', 'A/V es un siemens.']],
      'De $\\varepsilon = -L\\,dI/dt$: $L$ en V/(A/s).'),
    C('in-dos-corrientes', 'inductancia', 3, 'Dos bobinas idénticas llevan 1 A y 3 A. ¿Cómo son sus inductancias y sus enlaces de flujo?', 'Las inductancias son iguales; el enlace de flujo de la segunda es el triple',
      [['La segunda tiene el triple de inductancia', '$L$ depende de la geometría, no de $I$.'], ['Todo es igual en las dos', 'El flujo sí crece con $I$.'], ['La segunda tiene un tercio de inductancia', '$L$ es la misma.']],
      '$N\\Phi = LI$ con la misma $L$.'),

    /* ======================= Más: solenoide ======================= */
    C('so-que-A', 'solenoide', 1, 'En $L = \\mu_0N^2A/\\ell$, $A$ es…', 'el área de la sección transversal del solenoide',
      [['el área de la superficie del alambre', 'Es el área que encierra cada vuelta.'], ['el área total de todas las vueltas juntas', 'Es la de una sola vuelta; las vueltas ya están en $N^2$.'], ['el largo del solenoide', 'El largo es $\\ell$.']],
      'El área que atraviesa el flujo.'),
    N('so-diametro', 'solenoide', 1, { N: [100, 800, 100], d: [1, 6, 1], l: [10, 40, 5] },
      function (v) { return 'Un solenoide de aire de $' + v.N + '$ vueltas tiene $' + v.d + '\\ \\text{cm}$ de <strong>diámetro</strong> y $' + v.l + '\\ \\text{cm}$ de largo. ¿Cuánto vale su inductancia, en mH?'; },
      function (v) { return Lsol(v.N, v.d / 2, v.l, 1) * 1000; }, 'El radio es la mitad del diámetro.',
      { unit: 'mH', mistakes: { diam: function (v) { return Lsol(v.N, v.d, v.l, 1) * 1000; } }, feedback: [{ when: 'diam', say: 'Usaste el diámetro como radio: $r = d/2$.' }] },
      function (v, LM) { return IN(LM).ideal(v.N, v.d / 2, v.l, 1) * 1000; }),
    N('so-A', 'solenoide', 2, { L: [1, 20, 1], N: [200, 1000, 100], l: [10, 40, 5] },
      function (v) { return '¿Qué área de sección necesita un solenoide de aire de $' + v.N + '$ vueltas y $' + v.l + '\\ \\text{cm}$ de largo para tener $' + v.L + '\\ \\text{mH}$? En cm².'; },
      function (v) { return v.L / 1000 * (v.l / 100) / (MU0 * v.N * v.N) * 1e4; }, '$A = L\\ell/(\\mu_0N^2)$.',
      { unit: 'cm²', where: function (v) { var A = v.L / 1000 * (v.l / 100) / (MU0 * v.N * v.N) * 1e4; return A >= 0.1 && A <= 400; } },
      function (v, LM) { return v.L / 1000 / IN(LM).ideal(v.N, Math.sqrt(1 / Math.PI), v.l, 1); }),
    N('so-r', 'solenoide', 3, { L: [1, 20, 1], N: [200, 1000, 100], l: [10, 40, 5] },
      function (v) { return '¿Qué radio necesita un solenoide de aire de $' + v.N + '$ vueltas y $' + v.l + '\\ \\text{cm}$ de largo para tener $' + v.L + '\\ \\text{mH}$? En cm.'; },
      function (v) { return Math.sqrt(v.L / 1000 * (v.l / 100) / (MU0 * v.N * v.N) / Math.PI) * 100; }, '$r = \\sqrt{L\\ell/(\\pi\\mu_0N^2)}$.',
      { unit: 'cm', where: function (v) { var r = Math.sqrt(v.L / 1000 * (v.l / 100) / (MU0 * v.N * v.N) / Math.PI) * 100; return r >= 0.2 && r <= 12; } },
      function (v, LM) { return Math.sqrt(v.L / 1000 / IN(LM).ideal(v.N, 100, v.l, 1)) * 100; }),
    C('so-cortar', 'solenoide', 2, 'Cortas un solenoide largo por la mitad: cada pedazo tiene la mitad de vueltas y la mitad de largo. La inductancia de cada pedazo es…', 'la mitad de la original',
      [['la cuarta parte de la original', '$(N/2)^2/(\\ell/2) = N^2/(2\\ell)$.'], ['igual a la original', 'Bajan las vueltas más que el largo.'], ['el doble de la original', 'Baja, no sube.']],
      '$L \\propto N^2/\\ell$.'),
    C('so-unir', 'solenoide', 3, 'Pones dos solenoides idénticos uno tras otro y los conectas como un solo solenoide (doble de vueltas y doble de largo). Ignorando bordes, su inductancia es…', 'el doble de la de uno',
      [['la misma que la de uno', '$(2N)^2/(2\\ell) = 2N^2/\\ell$.'], ['cuatro veces la de uno', 'El largo también se duplica.'], ['la mitad de la de uno', 'Sube, no baja.']],
      '$L \\propto N^2/\\ell$.'),
    N('so-B-de-L', 'solenoide', 2, { L: [1, 20, 1], I: [0.5, 5, 0.5], N: [200, 1000, 100], A: [1, 10, 1] },
      function (v) { return 'Un solenoide de $' + v.N + '$ vueltas y $' + v.A + '\\ \\text{cm}^2$ de sección tiene $L = ' + v.L + '\\ \\text{mH}$ y lleva $' + fx(v.I, 1) + '\\ \\text{A}$. ¿Cuánto vale el campo dentro, en mT?'; },
      function (v) { return v.L / 1000 * v.I / (v.N * v.A * 1e-4) * 1000; }, '$NBA = LI$ → $B = LI/(NA)$.', { unit: 'mT' },
      function (v, LM) { return Math.abs(IN(LM).emf(v.L / 1000, v.I)) / (v.N * IN(LM).area(Math.sqrt(v.A / Math.PI))) * 1000; }),
    N('so-por-cm', 'solenoide', 2, { n: [5, 50, 5], r: [0.5, 2, 0.5], l: [10, 40, 5] },
      function (v) { return 'Un solenoide de aire de $' + v.l + '\\ \\text{cm}$ de largo y $' + fx(v.r, 1) + '\\ \\text{cm}$ de radio tiene $' + v.n + '$ vueltas por centímetro. ¿Cuánto vale su inductancia, en mH?'; },
      function (v) { return Lsol(v.n * v.l, v.r, v.l, 1) * 1000; }, '$N = n\\ell$ y $L = \\mu_0N^2A/\\ell$.', { unit: 'mH' },
      function (v, LM) { return IN(LM).ideal(v.n * v.l, v.r, v.l, 1) * 1000; }),

    /* ======================= Más: fem ======================= */
    C('fe-mayor', 'fem', 1, 'La fem autoinducida en una bobina es mayor cuando la corriente…', 'cambia más rápido',
      [['es más grande', 'Una corriente grande y constante no induce nada.'], ['es constante', 'Constante: fem cero.'], ['es pequeña', 'Importa la rapidez del cambio.']],
      '$|\\varepsilon| = L\\,|dI/dt|$.'),
    N('fe-henry', 'fem', 1, { L: [0.1, 2, 0.1], r: [1, 20, 1] },
      function (v) { return 'En una bobina de $' + fx(v.L, 1) + '\\ \\text{H}$ la corriente cambia a $' + v.r + '\\ \\text{A/s}$. ¿Cuánto vale $|\\varepsilon|$, en V?'; },
      function (v) { return v.L * v.r; }, '$|\\varepsilon| = L\\,|dI/dt|$.', { unit: 'V' },
      function (v, LM) { return Math.abs(IN(LM).emf(v.L, v.r)); }),
    N('fe-apaga', 'fem', 2, { L: [10, 400, 10], I: [0.5, 5, 0.5], dt: [1, 20, 1] },
      function (v) { return 'La corriente de $' + fx(v.I, 1) + '\\ \\text{A}$ en un inductor de $' + v.L + '\\ \\text{mH}$ baja uniformemente a cero en $' + v.dt + '\\ \\text{ms}$. ¿Cuánto vale la fem autoinducida (con su signo, recorriendo a favor de la corriente), en V?'; },
      function (v) { return v.L / 1000 * v.I / (v.dt / 1000); }, '$\\varepsilon = -L\\,dI/dt$ con $dI/dt < 0$: positiva.',
      { unit: 'V', mistakes: { neg: function (v) { return -v.L / 1000 * v.I / (v.dt / 1000); } }, feedback: [{ when: 'neg', say: 'La corriente baja: $dI/dt < 0$ y $\\varepsilon = -L\\,dI/dt$ es positiva.' }] },
      function (v, LM) { return IN(LM).emf(v.L / 1000, -v.I / (v.dt / 1000)); }),
    C('fe-sube-baja', 'fem', 2, 'La corriente en un inductor sube de 0 a 2 A en 1 ms y luego baja a 0 en 2 ms. Comparada con la de la subida, la fem durante la bajada…', 'es la mitad de grande y de signo contrario',
      [['es igual de grande y del mismo signo', 'La pendiente es la mitad y de signo opuesto.'], ['es el doble de grande', 'La bajada es más lenta: la mitad.'], ['es cero', 'La corriente cambia: hay fem.']],
      'Pendientes $+2$ A/ms y $-1$ A/ms.'),
    N('fe-mA', 'fem', 2, { L: [1, 50, 1], Im: [10, 200, 10], f: [1, 20, 1] },
      function (v) { return 'Por un inductor de $' + v.L + '\\ \\text{mH}$ pasa una corriente alterna de $' + v.Im + '\\ \\text{mA}$ de amplitud y $' + v.f + '\\ \\text{kHz}$. ¿Cuánto vale la fem máxima, en V?'; },
      function (v) { return v.L / 1000 * v.Im / 1000 * TAU * v.f * 1000; }, '$|\\varepsilon|_{\\max} = LI_m\\omega$, todo en SI.', { unit: 'V' },
      function (v, LM) { return Math.abs(IN(LM).emf(v.L / 1000, IN(LM).dIdt('sine', { Im: v.Im / 1000, f: v.f * 1000 }, 0))); }),
    C('fe-desfase', 'fem', 2, 'En un inductor con corriente alterna $I = I_m\\sin\\omega t$, la fem autoinducida…', 'está desfasada un cuarto de ciclo de la corriente (va con coseno)',
      [['está en fase con la corriente', 'La fem va con la derivada: coseno.'], ['está desfasada medio ciclo', 'Es un cuarto de ciclo.'], ['es constante', 'Es senoidal.']],
      'La derivada del seno es el coseno.'),
    N('fe-I-final', 'fem', 3, { L: [10, 200, 10], e: [1, 10, 1], t: [1, 10, 1], I0: [0.5, 2, 0.5] },
      function (v) { return 'Una bobina de $' + v.L + '\\ \\text{mH}$ lleva $' + fx(v.I0, 1) + '\\ \\text{A}$. Durante $' + v.t + '\\ \\text{ms}$ su fem autoinducida vale $-' + v.e + '\\ \\text{V}$ (se opone a un aumento). ¿Cuánta corriente lleva al final, en A?'; },
      function (v) { return v.I0 + v.e * (v.t / 1000) / (v.L / 1000); }, '$\\Delta I = |\\varepsilon|\\,\\Delta t/L$, y la corriente aumentó.',
      { unit: 'A', mistakes: { down: function (v) { return v.I0 - v.e * (v.t / 1000) / (v.L / 1000); } }, feedback: [{ when: 'down', say: 'Una fem negativa (en contra) indica que la corriente sube.' }] },
      function (v, LM) { return v.I0 + v.e / Math.abs(IN(LM).emf(v.L / 1000, 1)) * v.t / 1000; }),

    /* ======================= Más: núcleo ======================= */
    C('nu-ferrita', 'nucleo', 1, '¿Qué material es común como núcleo de inductores en circuitos de alta frecuencia?', 'La ferrita',
      [['El cobre', 'El cobre no es ferromagnético.'], ['El plástico', 'Tiene $K_m \\approx 1$.'], ['El vidrio', 'Tiene $K_m \\approx 1$.']],
      'Ferromagnética y poco conductora.'),
    C('nu-sacar', 'nucleo', 1, 'Si sacas el núcleo de hierro de una bobina, su inductancia…', 'baja mucho',
      [['sube mucho', 'El hierro la aumentaba.'], ['no cambia', 'El núcleo multiplica $L$ por $K_m$.'], ['se vuelve negativa', 'Solo baja a su valor de aire.']],
      'Pasa de $K_mL_0$ a $L_0$.'),
    N('nu-veces', 'nucleo', 2, { k: [4, 30, 1] },
      function (v) { return 'Un inductor de aire tiene cierta inductancia. Si le pones un núcleo de $K_m = ' + (v.k * v.k) + '$ y quieres conservar esa misma inductancia, ¿entre cuánto debes dividir el número de vueltas?'; },
      function (v) { return v.k; }, '$N \\propto 1/\\sqrt{K_m}$.',
      { unit: '', mistakes: { noSqrt: function (v) { return v.k * v.k; } }, feedback: [{ when: 'noSqrt', say: '$L \\propto K_mN^2$: el número de vueltas baja con $\\sqrt{K_m}$.' }] },
      function (v, LM) { return IN(LM).turnsFor(0.01, 1, 10, 1) / IN(LM).turnsFor(0.01, 1, 10, v.k * v.k); }),
    C('nu-400', 'nucleo', 2, 'Para la misma inductancia, una bobina con núcleo de $K_m = 400$ necesita, respecto a una de aire…', '20 veces menos vueltas',
      [['400 veces menos vueltas', 'Es $\\sqrt{400} = 20$.'], ['200 veces menos vueltas', 'Es la raíz, no la mitad.'], ['las mismas vueltas', 'El núcleo cambia $L$.']],
      '$N \\propto 1/\\sqrt{K_m}$.'),
    N('nu-fem', 'nucleo', 2, { N: [50, 300, 50], r: [0.5, 1.5, 0.5], l: [5, 20, 5], Km: [100, 500, 100], k: [1, 10, 1] },
      function (v) { return 'Una bobina de $' + v.N + '$ vueltas, $' + fx(v.r, 1) + '\\ \\text{cm}$ de radio y $' + v.l + '\\ \\text{cm}$ de largo tiene un núcleo de $K_m = ' + v.Km + '$. Si su corriente cambia a $' + v.k + '\\ \\text{A/s}$, ¿cuánto vale $|\\varepsilon|$, en mV?'; },
      function (v) { return Lsol(v.N, v.r, v.l, v.Km) * v.k * 1000; }, '$|\\varepsilon| = K_m\\mu_0N^2A/\\ell\\cdot dI/dt$.',
      { unit: 'mV', mistakes: { noKm: function (v) { return Lsol(v.N, v.r, v.l, 1) * v.k * 1000; } }, feedback: [{ when: 'noKm', say: 'Falta el factor $K_m$ del núcleo.' }] },
      function (v, LM) { return Math.abs(IN(LM).state({ N: v.N, r: v.r, l: v.l, Km: v.Km, kind: 'ramp', I0: 0, k: v.k }, 0).emf) * 1000; }),
    C('nu-paramagnetico', 'nucleo', 3, 'Un núcleo de aluminio (paramagnético, $K_m$ apenas mayor que 1) dentro de una bobina…', 'aumenta la inductancia de forma casi imperceptible',
      [['la multiplica por cientos', 'Eso hacen los ferromagnéticos.'], ['la reduce mucho', 'Paramagnético: la aumenta muy poco.'], ['la vuelve cero', 'No.']],
      '$K_m \\approx 1 + 10^{-5}$.'),
    N('nu-Km-medida', 'nucleo', 3, { N: [100, 500, 100], r: [0.5, 1.5, 0.5], l: [5, 20, 5], L: [50, 900, 50] },
      function (v) { return 'Una bobina de $' + v.N + '$ vueltas, $' + fx(v.r, 1) + '\\ \\text{cm}$ de radio y $' + v.l + '\\ \\text{cm}$ de largo con núcleo mide $L = ' + v.L + '\\ \\text{mH}$. ¿Cuánto vale $K_m$ del núcleo?'; },
      function (v) { return v.L / 1000 / Lsol(v.N, v.r, v.l, 1); }, '$K_m = L/(\\mu_0N^2A/\\ell)$.',
      { unit: '', where: function (v) { var k = v.L / 1000 / Lsol(v.N, v.r, v.l, 1); return k >= 5 && k <= 5000; } },
      function (v, LM) { return v.L / 1000 / IN(LM).ideal(v.N, v.r, v.l, 1); })
  ];

  K.register({
    'f3.S13.autoinduccion': 'Autoinducción',
    'f3.S13.inductancia': 'Inductancia: definición y unidades',
    'f3.S13.solenoide': 'Inductancia de un solenoide',
    'f3.S13.fem': 'Fem autoinducida',
    'f3.S13.nucleo': 'Núcleos magnéticos'
  }, Q);
})();
